add_filter( 'manage_edit-shop_coupon_columns', 'perfectpixel_coupon_sales_column' );
add_action( 'manage_shop_coupon_posts_custom_column', 'perfectpixel_coupon_sales_column_value', 10, 2 );

function perfectpixel_coupon_sales_column( $columns ) {
	$columns['perfectpixel_sales'] = '{{coupon_sales_column_title}}';
	return $columns;
}

function perfectpixel_coupon_sales_column_value( $column, $coupon_id ) {
	global $wpdb;
	if ( 'perfectpixel_sales' !== $column ) {
		return;
	}
	$key  = 'perfectpixel_coupon_sales_' . $coupon_id;
	$data = get_transient( $key );
	if ( false === $data ) {
		$data = $wpdb->get_row(
			$wpdb->prepare(
				"SELECT COUNT(DISTINCT s.order_id) AS orders, SUM(s.net_total) AS net
				FROM {$wpdb->prefix}wc_order_coupon_lookup c
				INNER JOIN {$wpdb->prefix}wc_order_stats s ON s.order_id = c.order_id
				WHERE c.coupon_id = %d AND s.status IN ('wc-completed','wc-processing')",
				$coupon_id
			),
			ARRAY_A
		);
		set_transient( $key, (array) $data, HOUR_IN_SECONDS );
	}
	$orders = (int) ( $data['orders'] ?? 0 );
	echo $orders ? esc_html( $orders ) . ' / ' . wp_kses_post( wc_price( (float) $data['net'] ) ) : '&ndash;';
}
